using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;
public static class C02InputState {public static object Run(){var p=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var pi=p.GetComponent<PlayerInput>();return new{playing=Application.isPlaying,paused=EditorApplication.isPaused,frame=Time.frameCount,scale=Time.timeScale,active=p.activeInHierarchy,components=p.GetComponents<Behaviour>().Select(c=>new{name=c.GetType().Name,c.enabled}).ToArray(),input=pi?new{pi.inputIsActive,pi.currentControlScheme,map=pi.currentActionMap?.name,enabled=pi.currentActionMap?.enabled,devices=pi.devices.Select(d=>d.displayName).ToArray(),move=pi.actions?.FindAction("Move")?.ReadValue<Vector2>().ToString()}:null,keyboard=Keyboard.current?.displayName,keysEnabled=Keyboard.current?.enabled};}}
